class CMultiFrameExpandContainer(MultiFrameExpandContainer):
    """C `for`-loop for multiframe expansion."""

    INDENT_BODY = True
    DEFAULT_LOCAL_VARIABLE_CLASS = CLocalVariable

    def generate_head_containers(self):
        if self._multiframe_variable is not None:
            expr = self._multiframe_variable.expr()
            yield from self.codelines_from_text(
                f"for ({expr} = {self._min_value}; {expr} < {self._max_value}; ++{expr}) {{"
            )

    def generate_foot_containers(self):
        if self._multiframe_variable is not None:
            yield from self.codelines_from_text("}")


class CIntCombineExpandContainer(IntCombineExpandContainer):
    """Helper container combining split integer loop indices in C."""

    INDENT_BODY = True
    DEFAULT_LOCAL_VARIABLE_CLASS = CLocalVariable

    def generate_head_containers(self, **_):
        yield from self.codelines_from_text(
            f"{self._multiframe_variable.local} = {self._second.local} * {self._first.max_value} + {self._first.local}"
            + (
                f" + {self._multiframe_variable.min_value}"
                if self._multiframe_variable.min_value
                else ""
            )
            + ";"
        )
        yield from self.codelines_from_text(
            f"if ({self._multiframe_variable.local} < {self._multiframe_variable.max_value}) {{"
        )

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text("}")


class CRoutineContainer(RoutineContainer):
    """C function container."""

    INDENT_BODY = True
    INPUT_VARIABLE_CLASS = CInputVariable

    def get_signature(self, *, terminate=False):
        call_args = list(
            variable.as_argument_declaration()
            for variable in self.get_argument_variables()
        )
        if not call_args:
            args_string = "void"
        else:
            args_string = ", ".join(call_args)
        suffix = ";" if terminate else ""
        return f"void {self.name}({args_string}){suffix}"

    def generate_head_containers(self, **_):
        yield from self.codelines_from_text(
            self.get_signature(terminate=False)
        )
        yield from self.codelines_from_text("{")

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text("}")

    def generate_prmb_containers(self, **kwargs):
        local_variables = list(self.get_local_variables())
        if not local_variables:
            return
        yield from self.comment_from_text("LOCAL") or []
        for variable in local_variables:
            yield DefinitionLines(variable, context=self.context, **kwargs)
        yield from self.codelines_from_text("")


class CAccumulateStatementLine(AccumulateStatementLine):
    """C accumulation statement."""

    UPDATE_BLUEPRINT = "{target} += {expression};"


class CAffineContainer(CAccumulateStatementLine):
    """Affine update operation `y += a * x + b`."""

    EXPRESSION_BLUEPRINT = "{a_value} * {x_expression} + {b_value}"

    def __init__(self, y, a, x, b, *, context, **params):
        super().__init__(
            target=y,
            value_dict={
                "target": y,
                "x_expression": x,
                "a_value": a,
                "b_value": b,
            },
            context=context,
            **params,
        )
        self.requires(y)
        self.requires(x)
        self.requires(a)
        self.requires(b)


class CBilinearContainer(CAccumulateStatementLine):
    """Bilinear update operation `z += a * x * y`."""

    EXPRESSION_BLUEPRINT = "{a_value} * {u_expression} * {v_expression}"

    def __init__(self, y, a, u, v, *, context, **params):
        super().__init__(
            target=y,
            value_dict={
                "target": y,
                "u_expression": u,
                "v_expression": v,
                "a_value": a,
            },
            context=context,
            **params,
        )
        self.requires(y)
        self.requires(u)
        self.requires(v)
        self.requires(a)


