class CBuilder(Builder, identifier="C"):
    """C Builder."""

    _assignment_class = CAssignmentStatementLine

    def create_libroutine_variable(
        self,
        *,
        name,
        dtype,
        status,
        size,
        assignment=None,
        namespace=None,
        **kwargs,
    ):
        if status & LibRoutineVariable.STATUS_BUFFER:
            return CBufferVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        status = status & 3
        if status == LibRoutineVariable.STATUS_INPUT:
            return CInputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == LibRoutineVariable.STATUS_OUTPUT:
            return COutputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == LibRoutineVariable.STATUS_INOUT:
            return CInOutVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        return super().create_libroutine_variable(
            name=name,
            dtype=dtype,
            status=status,
            size=size,
            namespace=namespace,
            **kwargs,
        )

    def as_numeric(self, variable):
        return CNumeric(variable)

    def lookup_status(self, status):
        if status.upper().strip() == "OUT":
            status = "INOUT"
        return super().lookup_status(status)

    def check_relevance(self, *variables, hook=None):
        remember = []
        for var in variables:
            if var is None:
                return False
            if isinstance(var, LibRoutineVariable):
                remember.append(var)
                continue
            if abs(var) < ZERO_TOL:
                return False
        if hook is not None:
            for var in remember:
                hook.requires(var)
        return True

    def handle_affine_instruction(self, instruction, context, buildargs):
        instruction_dict = instruction.apply_environment(
            context.environment
        ).contribute_to_dict()

        tgt0 = instruction_dict.get("tgt0")
        src0 = instruction_dict.get("src0")
        alpha = instruction_dict.get("alpha", 1)
        beta = instruction_dict.get("beta", 0)

        x_var_real = context.namespace.find_assignment(
            type(src0), "real", exception_not_existing=False
        )
        x_var_imag = context.namespace.find_assignment(
            type(src0), "imag", exception_not_existing=False
        )
        y_var_real = context.namespace.find_assignment(
            type(tgt0), "real", exception_not_existing=False
        )
        y_var_imag = context.namespace.find_assignment(
            type(tgt0), "imag", exception_not_existing=False
        )

        x_var_offs = src0.offsets
        y_var_offs = tgt0.offsets
        a_real = self.wrap_lrv(alpha.real)
        a_imag = self.wrap_lrv(alpha.imag)
        b_real = self.wrap_lrv(beta.real)
        b_imag = self.wrap_lrv(beta.imag)

        combinations = [
            (y_var_real, a_real, x_var_real, b_real, 1),
            (y_var_real, a_imag, x_var_imag, b_real, -1),
            (y_var_imag, a_real, x_var_imag, b_imag, 1),
            (y_var_imag, a_imag, x_var_real, b_imag, 1),
        ]
        hook = HookContainer(context=context)
        first_real = True
        first_imag = True
        for y_var, a_val, x_var, b_val, sign in combinations:
            if y_var is y_var_real and not first_real:
                b_val = self.wrap_lrv(0.0)
            if y_var is y_var_imag and not first_imag:
                b_val = self.wrap_lrv(0.0)
            ret = self.check_relevance(y_var, a_val, x_var, b_val, hook=hook)
            if ret:
                yield CAffineContainer(
                    y_var.at(*y_var_offs),
                    a_val * sign,
                    x_var.at(*x_var_offs),
                    b_val,
                    context=context,
                )
                if y_var is y_var_real:
                    first_real = False
                else:
                    first_imag = False

        yield CodeLine("", context=context)

    def handle_bilinear_instruction(self, instruction, context, buildargs):
        instruction_dict = instruction.apply_environment(
            context.environment
        ).contribute_to_dict()

        tgt0 = instruction_dict.get("tgt0")
        src0 = instruction_dict.get("src0")
        src1 = instruction_dict.get("src1")
        alpha = instruction_dict.get("alpha")

        u_var_real = context.namespace.find_assignment(
            type(src0), "real", exception_not_existing=False
        )
        u_var_imag = context.namespace.find_assignment(
            type(src0), "imag", exception_not_existing=False
        )
        v_var_real = context.namespace.find_assignment(
            type(src1), "real", exception_not_existing=False
        )
        v_var_imag = context.namespace.find_assignment(
            type(src1), "imag", exception_not_existing=False
        )
        y_var_real = context.namespace.find_assignment(
            type(tgt0), "real", exception_not_existing=False
        )
        y_var_imag = context.namespace.find_assignment(
            type(tgt0), "imag", exception_not_existing=False
        )

        u_var_offs = src0.offsets
        v_var_offs = src1.offsets
        y_var_offs = tgt0.offsets
        a_real = self.wrap_lrv(alpha.real)
        a_imag = self.wrap_lrv(alpha.imag)

        include_all = False

        hook = HookContainer(context=context)

        ret = self.check_relevance(
            y_var_real, a_real, u_var_real, v_var_real, hook=hook
        )
        if ret or include_all:
            yield CBilinearContainer(
                y_var_real.at(*y_var_offs),
                a_real,
                u_var_real.at(*u_var_offs),
                v_var_real.at(*v_var_offs),
                context=context,
            )

        ret = self.check_relevance(
            y_var_real, a_real, u_var_imag, v_var_imag, hook=hook
        )
        if ret or include_all:
            yield CBilinearContainer(
                y_var_real.at(*y_var_offs),
                -a_real,
                u_var_imag.at(*u_var_offs),
                v_var_imag.at(*v_var_offs),
                context=context,
            )

        ret = self.check_relevance(
            y_var_real, a_imag, u_var_imag, v_var_real, hook=hook
        )
        if ret or include_all:
            yield CBilinearContainer(
                y_var_real.at(*y_var_offs),
                -a_imag,
                u_var_imag.at(*u_var_offs),
                v_var_real.at(*v_var_offs),
                context=context,
            )

        ret = self.check_relevance(
            y_var_real, a_imag, u_var_real, v_var_imag, hook=hook
        )
        if ret or include_all:
            yield CBilinearContainer(
                y_var_real.at(*y_var_offs),
                -a_imag,
                u_var_real.at(*u_var_offs),
                v_var_imag.at(*v_var_offs),
                context=context,
            )

        ret = self.check_relevance(
            y_var_imag, a_real, u_var_imag, v_var_real, hook=hook
        )
        if ret or include_all:
            yield CBilinearContainer(
                y_var_imag.at(*y_var_offs),
                a_real,
                u_var_imag.at(*u_var_offs),
                v_var_real.at(*v_var_offs),
                context=context,
            )

        ret = self.check_relevance(
            y_var_imag, a_real, u_var_real, v_var_imag, hook=hook
        )
        if ret or include_all:
            yield CBilinearContainer(
                y_var_imag.at(*y_var_offs),
                a_real,
                u_var_real.at(*u_var_offs),
                v_var_imag.at(*v_var_offs),
                context=context,
            )

        ret = self.check_relevance(
            y_var_imag, a_imag, u_var_real, v_var_real, hook=hook
        )
        if ret or include_all:
            yield CBilinearContainer(
                y_var_imag.at(*y_var_offs),
                a_imag,
                u_var_real.at(*u_var_offs),
                v_var_real.at(*v_var_offs),
                context=context,
            )

        ret = self.check_relevance(
            y_var_imag, a_imag, u_var_imag, v_var_imag, hook=hook
        )
        if ret or include_all:
            yield CBilinearContainer(
                y_var_imag.at(*y_var_offs),
                -a_imag,
                u_var_imag.at(*u_var_offs),
                v_var_imag.at(*v_var_offs),
                context=context,
            )
        yield CodeLine("", context=context)

    def create_external_array(self, *args, context, **kwargs):
        return Builder.create_external_array(
            self,
            *args,
            context=context,
            local_class=CLocalVariable,
            constant_class=CConstant,
        )


class CComputeResource(ComputeResource):
    """Compute resource for C code generation."""

    DEFAULT_LOCAL_VARIABLE_CLASS = CLocalVariable

    def create_mfe_container(
        self,
        *,
        context,
        local_variable_capture,
        name=None,
        loop_container=None,
        loop_capture=None,
    ) -> None | MultiFrameExpandContainer:
        del name, loop_container, loop_capture
        return CMultiFrameExpandContainer(
            context=context,
            local_variable_capture=local_variable_capture,
        )

    def create_combine_container(
        self,
        first,
        second,
        *,
        context,
        local_variable_capture,
        name=None,
        loop_container=None,
        loop_capture=None,
    ) -> None | MultiFrameExpandContainer:
        del name, loop_container, loop_capture
        return CIntCombineExpandContainer(
            first,
            second,
            context=context,
            local_variable_capture=local_variable_capture,
        )


class CLibRoutine(LibRoutine):
    """C LibRoutine variant."""


class CLibrary(Library):
    """C source and header emission."""

    BACKEND_IDENTIFIER = "c"
    FILEENDING = "c"
    INDENTSTR = "    "
    LIBROUTINE_CLASS = CLibRoutine
    IMPORTLINE_CLASS = CImportContainer
    DEFAULT_BUILDER = CBuilder
    DEFAULT_CONTAINER_CLASS = CRoutineContainer

    def __init__(
        self,
        plain_name,
        build_hash=None,
        resource=None,
        configuration=None,
        general_configuration=None,
    ):
        if resource is None:
            resource = CComputeResource("CResource")
        self._initialize_library_state(
            plain_name=plain_name,
            build_hash=build_hash,
            resource=resource,
            import_section_class=CImportSectionContainer,
            backend_configuration=configuration,
            general_configuration=general_configuration,
        )
        self._meta["header_name"] = self.headername

    @property
    def headername(self):
        return self._get_headername()

    def _get_headername(self):
        return f"{self.libname}.h"

    @property
    def objectname(self):
        return self._get_objectname()

    def _get_objectname(self):
        return f"{self.libname}.o"

    @property
    def sharedlibname(self):
        return self._get_sharedlibname()

    def _get_sharedlibname(self):
        return f"lib{self.libname}.so"

    @property
    def header_guard(self):
        return self._get_header_guard()

    def _get_header_guard(self):
        return f"PHOENIX_{self.libname.upper()}_H"

    def write_all_files(self):
        self.write_code()
        self.write_header()
        self.write_docs()
        self.write_manifest()
        return True

    def write_header(self):
        self.ensure_output_dir()
        self.write_basepath_file(self.headername, lines=self.get_header_lines())

    def get_output_files(self):
        yield from super().get_output_files()
        yield self.headername

    def get_compilation_output_files(self):
        yield self.objectname
        yield self.sharedlibname

    def get_header_lines(self):
        yield f"#ifndef {self.header_guard}"
        yield f"#define {self.header_guard}"
        yield ""
        yield "#include <stdint.h>"
        yield ""
        yield "#ifdef __cplusplus"
        yield 'extern "C" {'
        yield "#endif"
        yield ""
        for _name, libroutine in self.content:
            yield self.get_libroutine_signature(
                libroutine, terminate=True
            )
        yield ""
        yield "#ifdef __cplusplus"
        yield "}"
        yield "#endif"
        yield ""
        yield f"#endif  /* {self.header_guard} */"

    def get_libroutine_signature(self, libroutine, *, terminate=False):
        """Render a C signature for a generated or raw-code routine."""
        if libroutine.container is not None:
            return libroutine.container.get_signature(terminate=terminate)
        call_args = [
            variable.as_argument_declaration()
            for variable in libroutine.get_arguments()
        ]
        args_string = "void" if not call_args else ", ".join(call_args)
        suffix = ";" if terminate else ""
        return f"void {libroutine.name}({args_string}){suffix}"

    def get_to_zero_support_routine(self, dtype):
        """Return the external helper routine used to reset one buffer."""
        routine_name = f"phoenix_to_zero_{dtype}"
        existing = self[routine_name]
        if existing is not None:
            return existing
        zero_value = CLocalVariable(name="tmp", dtype=dtype, no_entry=True).get_zero_value()
        ctype = CLocalVariable.DTYPE_LOOKUP[dtype]
        code = [
            f"void {routine_name}({ctype} *buffer, int32_t size)",
            "{",
            "    for (int32_t idx = 0; idx < size; ++idx) {",
            f"        buffer[idx] = {zero_value};",
            "    }",
            "}",
        ]
        return self._register_manual_routine(
            routine_name,
            code=code,
            arguments=[
                {
                    "name": "buffer",
                    "dtype": dtype,
                    "size": 1,
                    "status": "INOUT",
                    "assignment": ("buffer", "data"),
                },
                {
                    "name": "size",
                    "dtype": "i32",
                    "status": "IN",
                },
            ],
        )

    def generate_head_containers(self, **_):
        yield from self.codelines_from_text(f'#include "{self.libname}.h"')
        support_header = self.backend_configuration.get_nested(
            "support", "header_name", default=None
        )
        if support_header:
            yield from self.codelines_from_text(f'#include "{support_header}"')

    def generate_foot_containers(self, **_):
        return
        yield

    def generate_prmb_containers(self, **_):
        imports = list(self.import_capture.list_imports())
        if imports:
            yield from self.codelines_from_text("")
            for library, routines in imports:
                yield CImportContainer(library, routines, context=self.context)

        constants = list(self.definition_capture.captured)
        if constants:
            yield from self.codelines_from_text("")
            for variable in constants:
                for line in variable.get_definition_lines():
                    yield from self.codelines_from_text(line)

        if not self.backend_configuration.get_nested(
            "support", "header_name", default=None
        ):
            yield from self.codelines_from_text("")
            for dtype, ctype, zero_value in (
                ("f64", "double", "0.0"),
                ("f32", "float", "0.0f"),
                ("i64", "int64_t", "0"),
                ("i32", "int32_t", "0"),
            ):
                yield from self.codelines_from_text(
                    f"static inline void phoenix_zero_{dtype}({ctype} *buffer, int32_t size) {{"
                )
                yield from self.codelines_from_text(
                    "    for (int32_t idx = 0; idx < size; ++idx) {"
                )
                yield from self.codelines_from_text(
                    f"        buffer[idx] = {zero_value};"
                )
                yield from self.codelines_from_text("    }")
                yield from self.codelines_from_text("}")
                yield from self.codelines_from_text("")

    def generate_clsg_containers(self, **_):
        return
        yield

    def get_header_target(self):
        return MFTHeader(self.relative_to_basepath(self.headername))

    def get_support_target(self):
        support_makefile = self.backend_configuration.get_nested(
            "support", "makefile", default=None
        )
        support_root = self.backend_configuration.get_nested(
            "support", "root", default=None
        )
        build_target = self.backend_configuration.get_nested(
            "support", "build_target", default=None
        )
        support_library = self.backend_configuration.get_nested(
            "support", "library_file", default=None
        )
        if not support_makefile or not support_root or not build_target:
            return None
        required = [support_library] if support_library else []
        return BackendSupportBuildTarget(
            f"support_{self.libname}_{type(self).BACKEND_IDENTIFIER}",
            support_root=support_root,
            makefile=support_makefile,
            build_target=build_target,
            required_files=required,
        )

    def get_object_target(self):
        dependencies = [*self.get_makefile_compile_dependency_targets()]
        return CMFTObject(
            self.relative_to_basepath(self.objectname),
            source=self.get_codefile_target(),
            dependencies=[self.get_header_target(), *dependencies],
            configuration=self.backend_configuration,
        )

    def get_library_target(self):
        dependencies = [
            self.get_object_target(),
            *self.get_makefile_dependency_targets(),
        ]
        support_target = self.get_support_target()
        if support_target is not None:
            dependencies.append(support_target)
        return CMFTSharedLibrary(
            self.relative_to_basepath(self.sharedlibname),
            dependencies=dependencies,
            configuration=self.backend_configuration,
        )

    def get_makefile_targets(self):
        yield self.get_codefile_target()
        yield self.get_header_target()
        yield self.get_object_target()
        yield self.get_library_target()


CBuilder.set_instruction_class_handler(
    AffineOperationInstruction, CBuilder.handle_affine_instruction
)
CBuilder.set_instruction_class_handler(
    BiLinearOperationInstruction, CBuilder.handle_bilinear_instruction
)

CRoutineContainer.set_comment_class(CCommentLine)

CBuilder.set_comment_class(CCommentLine)
CBuilder.set_routinecall_class(CRoutineCallContainer)
register_c_atomic_handlers(CBuilder)
